#ifndef RING_H
#define RING_H

#define ENTRY_LEN 48

/* A fixed-size log that keeps the newest `capacity` entries, overwriting the oldest. */
typedef struct {
    char (*entries)[ENTRY_LEN];
    int capacity;
    int start;     /* index of the oldest entry */
    int count;     /* entries in use */
    long total;    /* entries ever pushed */
} Ring;

int ring_init(Ring *r, int capacity);          /* 0 on success, -1 if out of memory */
void ring_free(Ring *r);
void ring_push(Ring *r, const char *text);     /* copies at most ENTRY_LEN - 1 characters */
/* The k-th newest entry (k = 0 is the newest), or NULL if k >= count. */
const char *ring_newest(const Ring *r, int k);
void ring_clear(Ring *r);

#endif

#include <stdlib.h>
#include <string.h>
#include "ring.h"

int ring_init(Ring *r, int capacity) {
    r->entries = malloc((size_t)capacity * sizeof *r->entries);
    if (r->entries == NULL) return -1;
    r->capacity = capacity;
    r->start = r->count = 0;
    r->total = 0;
    return 0;
}

void ring_free(Ring *r) {
    free(r->entries);
    r->entries = NULL;
}

void ring_push(Ring *r, const char *text) {
    /* Milestone 1: write after the newest entry; when full, overwrite the oldest and move start. */
    (void)r; (void)text;
}

const char *ring_newest(const Ring *r, int k) {
    /* Milestone 1: the newest is at (start + count - 1) % capacity. */
    (void)r; (void)k;
    return NULL;
}

void ring_clear(Ring *r) {
    (void)r;   /* Milestone 2 */
}

#include <stdio.h>
#include <string.h>
#include "ring.h"

int main(void) {
    Ring log;
    int ready = 0;
    char line[256], cmd[16];
    while (fgets(line, sizeof line, stdin) != NULL) {
        line[strcspn(line, "\n")] = '\0';
        if (sscanf(line, "%15s", cmd) != 1) continue;
        int n;
        if (strcmp(cmd, "INIT") == 0 && sscanf(line, "%*s %d", &n) == 1 && n >= 1 && n <= 1000 && !ready) {
            if (ring_init(&log, n) != 0) return 1;
            ready = 1;
            printf("log of %d entries\n", n);
        } else if (!ready) {
            printf("error: no log yet\n");
        } else if (strcmp(cmd, "PUSH") == 0 && strlen(line) > 5) {
            ring_push(&log, line + 5);
            printf("ok %ld\n", log.total);
        } else if (strcmp(cmd, "LAST") == 0 && sscanf(line, "%*s %d", &n) == 1 && n >= 1) {
            if (log.count == 0) printf("empty\n");
            for (int k = 0; k < n && ring_newest(&log, k) != NULL; k++) printf("%d: %s\n", k + 1, ring_newest(&log, k));
        } else if (strcmp(cmd, "COUNT") == 0) {
            printf("%d kept, %ld pushed\n", log.count, log.total);
        } else if (strcmp(cmd, "CLEAR") == 0) {
            ring_clear(&log);
            printf("cleared\n");
        } else {
            printf("error: bad command %s\n", line);
        }
    }
    if (ready) ring_free(&log);
    return 0;
}

