#include <stdlib.h>
#include <string.h>
#include "ring.h"

int ring_init(Ring *r, int capacity) {
    r->entries = malloc((size_t)capacity * sizeof *r->entries);
    if (r->entries == NULL) return -1;
    r->capacity = capacity;
    r->start = r->count = 0;
    r->total = 0;
    return 0;
}

void ring_free(Ring *r) {
    free(r->entries);
    r->entries = NULL;
}

void ring_push(Ring *r, const char *text) {
    int slot = (r->start + r->count) % r->capacity;
    if (r->count == r->capacity) {
        slot = r->start;                          /* overwrite the oldest */
        r->start = (r->start + 1) % r->capacity;
    } else {
        r->count++;
    }
    strncpy(r->entries[slot], text, ENTRY_LEN - 1);
    r->entries[slot][ENTRY_LEN - 1] = '\0';
    r->total++;
}

const char *ring_newest(const Ring *r, int k) {
    if (k < 0 || k >= r->count) return NULL;
    return r->entries[(r->start + r->count - 1 - k) % r->capacity];
}

void ring_clear(Ring *r) {
    r->start = r->count = 0;
}
